#!/usr/bin/env python3
"""Emit the pure-step Fe tests (src/tests_vectors.fe) from vectors.json."""
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
v = json.load(open(os.path.join(here, "vectors.json")))
out = [
    "// GENERATED by ref/gen_tests.py from ref/vectors.json (ref/life.py, per-cell reference).",
    "// Do not edit by hand. Bit index = row * 16 + col.",
    "use super::board::{step, step_n}",
    "",
]
for name, d in v.items():
    start = d["start"]
    for n, end in d["steps"].items():
        out.append("#[test]")
        out.append(f"fn vec_{name}_{n}() {{")
        out.append(f"    assert(step_n({start:#x}, {n}) == {end:#x})")
        if n == "1":
            out.append(f"    assert(step({start:#x}) == {end:#x})")
        out.append("}")
        out.append("")
open(os.path.join(here, "..", "src", "tests_vectors.fe"), "w").write("\n".join(out))
